using System;
using System.Globalization;
using System.Linq;
using MET.Core;
using UnityEngine;
using UnityEngine.UI;
namespace MET.City {
public sealed partial class CityInterface {
 string _tradeResource="food",_tradeSide="buy",_tradeAmount="12",_tradeLimit="";
 void MarketPage(){if(_pageContext=="food"||_pageContext=="material"||_pageContext=="goods")_tradeResource=_pageContext;var capacity=Card(_body,"真实在线货运能力","外部市场只按真实活跃在线时间运行；本地加速不同比扩大运力。",Blue);Metric(capacity,"共享运力",F(Market._total_capacity(G))+" 单位 / 现实在线小时");var ledger=S["block"].Get("trade_ledger",V.Arr());if(ledger.Count!=0)Meter(capacity,"最近周期使用",ledger[-1]["used_capacity"].Double,ledger[-1]["capacity"].Double," 单位",Blue);
  var quoteRow=Row(_body,"Shared Market Quotes",190);foreach(var resource in new[]{"food","material","goods"}){var r=resource;var q=Market.quote(G,r);var card=Card(quoteRow,Resource(r),"共享报价 · 压力影响下次报价",r=="food"?Green:r=="material"?Gold:Blue);Metric(card,"买入",F(q.Get("buy_price",0).Double,3));Metric(card,"卖出",F(q.Get("sell_price",0).Double,3));Button(card,(_tradeResource==r?"✓ ":"")+"交易此资源",()=>{_tradeResource=r;_tradeLimit="";_pageContext="";RenderPage();});}
  var order=Card(_body,"创建限价订单","一批订单在同一次结算中使用冻结报价，按稳定次序共享运力。",Blue);var sides=Row(order);Button(sides,(_tradeSide=="buy"?"✓ ":"")+"买入",()=>{_tradeSide="buy";_tradeLimit="";RenderPage();});Button(sides,(_tradeSide=="sell"?"✓ ":"")+"卖出",()=>{_tradeSide="sell";_tradeLimit="";RenderPage();});var quote=Market.quote(G,_tradeResource);var price=quote.Get(_tradeSide+"_price",0).Double;if(_tradeLimit=="")_tradeLimit=price.ToString("F3",CultureInfo.InvariantCulture);
  Label(order,Resource(_tradeResource)+" · "+(_tradeSide=="buy"?"买价不高于限价才成交":"卖价不低于限价才成交"),17,Gold);Label(order,price<0?(_tradeSide=="buy"?"当前为负买价：接收资源时收到通货，仍受仓容和运力限制。":"当前为负卖价：外运资源时支付处置通货，余额不足只成交可负担部分。"):(_tradeSide=="buy"?"买入支付通货，并需要实际空仓容。":"卖出收到通货，并真正扣除库存。"),16,Muted);
  var inputs=Row(order,"Trade Entry",78);var aq=Column(inputs,"Amount",1);Label(aq,"数量",15,Muted);var amount=InputBox(aq,_tradeAmount,"输入正数量");amount.onValueChanged.AddListener(v=>_tradeAmount=v);var lq=Column(inputs,"Limit",1);Label(lq,"每单位限价（可为负）",15,Muted);var limit=InputBox(lq,_tradeLimit,"输入限价");limit.onValueChanged.AddListener(v=>_tradeLimit=v);
  Button(order,"提交 "+Resource(_tradeResource)+"限价订单",()=>{if(!double.TryParse(_tradeAmount,NumberStyles.Float,CultureInfo.InvariantCulture,out var quantity)||!double.TryParse(_tradeLimit,NumberStyles.Float,CultureInfo.InvariantCulture,out var limitPrice)){ShowMessage("请输入有效数量与限价。");return;}Command(g=>Market.order(g,_tradeResource,_tradeSide,quantity,limitPrice));},true,Market._total_capacity(G)<=.000001);
  var orders=Card(_body,"订单与成交","等待限价、仓容、库存、现金或共享运力时，订单继续保留。",Blue);foreach(var item in S["block"]["trade_orders"].Reverse()){var id=item["id"].Text;var row=Row(orders,"Order "+id,54);Label(row,Resource(item["resource"].Text)+" · "+(item["side"].Text=="buy"?"买入":"卖出"),18);Label(row,F(item["remaining"].Double)+" / "+F(item["amount"].Double)+" · 限价 "+F(item["limit_price"].Double,3),17,Gold);var status=item["status"].Text;Label(row,V.Map("open","等待成交","partial","部分成交","filled","全部成交","cancelled","已取消").Get(status,status).Text,16,Muted);if(status=="open"||status=="partial")Button(row,"取消订单",()=>Command(g=>Market.cancel(g,id)));}
  Fold(orders,"真实成交记录",c=>{foreach(var trade in S["block"]["trade_history"].Reverse().Take(100)){Label(c,Resource(trade["resource"].Text)+" · "+(trade["side"].Text=="buy"?"买入":"卖出")+" "+F(trade["amount"].Double,3)+" × "+F(trade["unit_price"].Double,3)+" · 通货 "+Signed(trade["currency_delta"].Double),16);Fold(c,"运力提供来源与成交凭据",raw=>Raw(raw,trade));}});
 }
 string _policySlot="Tax";
 void PoliciesPage(){var slots=Row(_body,"Policy Slots");foreach(var slotValue in new[]{"Tax","Labor","Environment","Procurement","Land"}){var slot=slotValue;Button(slots,V.Map("Tax","税收","Labor","用工","Environment","环境","Procurement","采购","Land","土地").Get(slot,slot).Text,()=>{if(_comparisonValid)ClearComparison();_policySlot=slot;RenderPage();});}
  Label(_body,"同槽政策互斥 · 每次更换 "+F(G.c.balance["policy_switch_price"].Double,0)+"通货",18,Gold);var baseline=_planner.snapshot(G);foreach(var idValue in Rules.ids(G.c.policies)){var id=idValue.Text;var policy=G.c.policies[id];if(policy["slot"].Text!=_policySlot)continue;var current=S["block"]["policies"].Get(_policySlot,"").Text==id;var card=Card(_body,policy["name"].Text+(current?"  / 正在采用":""),policy.Get("summary","").Text,current?Green:Blue);var preview=_planner.policy(G,id);if(preview["ok"].Bool){Metric(card,"同一步下一周期经营",F(preview["cashflow"].Double)+" /月");Metric(card,"相对不更换",Signed(preview["delta"].Double)+" /月","两边都来自真实下一步结算。",preview["delta"].Double>=0?Green:Gold);var row=Row(card);Button(row,"地图 · 现状预测",()=>{_baseline=baseline;_proposal=preview;PublishComparison();ShowForecastMap("baseline",baseline);});Button(row,"地图 · 更换后",()=>{_baseline=baseline;_proposal=preview;PublishComparison();ShowForecastMap("proposal",preview["map_snapshot"]);});}else Label(card,preview.Get("error","预测不可用").Text,16,Gold);
   var version=_planner.version(G);Button(card,current?"已经采用":"支付并更换政策",()=>{if(version!=_planner.version(G)){RenderPage();ShowMessage("城市已变化，预测已刷新，请重新核对。");return;}Command(g=>g.switch_policy(id));},!current,current||!preview.Get("ok",false).Bool);Fold(card,"完整政策规则",c=>Raw(c,policy));}
 }
 void TenderPage(){var draft=S["draft"];if(draft.Count==0){Label(_body,"尚未选择建设场地。请回到地图点选空闲陆地。",23,Muted);return;}var offers=draft["offers"];if(offers.Count==0)return;if(!offers.Any(x=>x["id"].Text==_offer))_offer=offers[0]["id"].Text;_baseline=_planner.snapshot(G);var previews=V.Map();foreach(var item in offers)previews[item["id"]]=_planner.compare(G,draft["base"].Text,draft["tile"].Text,item);var selected=offers.First(x=>x["id"].Text==_offer);_proposal=previews[_offer];_previewVersion=_planner.version(G);PublishComparison();
  var cost=Draft.offer_cost(G,selected);var action=Card(_body,G.c.projects[draft["base"]]["name"].Text+" · 地块 "+draft["tile"].Text,"同一步比较：不建设，与假定选中方案已完工。施工、支付和材料另计。",Gold);Metric(action,"共同建设成本",F(cost["currency"].Double,0)+"通货 · "+F(cost["material"].Double,0)+"材料 · "+F(cost["cp"].Double)+" CP");
  var row=Row(_body,"Operator Offers",330);double maxFood=0,maxHousing=0;foreach(var result in previews.Values)if(result.Get("ok",false).Bool){maxFood=Math.Max(maxFood,result["outputs"].Get("food",0).Double);maxHousing=Math.Max(maxHousing,Math.Abs(result["housing"].Double));}foreach(var item in offers){var offer=item;var org=G.c.operators[item["operator_org"]];var result=previews[item["id"]];var card=Card(row,(_offer==item["id"].Text?"✓ ":"")+org["name"].Text,org.Get("summary","").Text,_offer==item["id"].Text?Gold:Blue);Label(card,"T1 → T2 → T3\n"+string.Join(" → ",item["slot_track"].Select(x=>Catalog.SLOT_NAMES.Get(x,x).Text)),16,Muted,65);if(result.Get("ok",false).Bool){if(maxFood>0)Meter(card,"预计粮食产出",result["outputs"].Get("food",0).Double,maxFood," /月",Green);if(maxHousing>0)Meter(card,"住房容量增加",result["housing"].Double,maxHousing," 人",Blue);Metric(card,"实际运行",F(result["activity"].Get("utilization",0).Double*100)+"%");}else Label(card,result.Get("error","预测不可用").Text,16,Gold);Button(card,"选择此运营者",()=>{_offer=offer["id"].Text;RenderPage();});}
  if(_proposal.Get("ok",false).Bool){Impact(_body,_baseline,_proposal);var map=Row(_body);Button(map,"地图 · 现状预测",()=>ShowForecastMap("baseline",_baseline));Button(map,"地图 · 建成后",()=>ShowForecastMap("proposal",_proposal["map_snapshot"]));Button(map,"本次改变图层",()=>{SetLayer("delta");ShowForecastMap("proposal",_proposal["map_snapshot"]);});}
  var controls=Row(_body,"Tender Decision",54);var reroll=Draft.reroll_cost(G);Button(controls,"换一组 · "+F(reroll["currency"].Double,0)+"通货",()=>{Command(g=>g.reroll(),false);_offer="";RenderPage();});Button(controls,"采用并建设 · "+F(cost["currency"].Double,0)+"通货",()=>{if(_previewVersion!=_planner.version(G)){RenderPage();ShowMessage("城市已变化，预测已刷新。请重新核对。");return;}var id=_offer;var targetTile=draft["tile"].Text;var error=Runtime.Execute(g=>g.accept_offer(id));if(error==""){CloseArchive();SelectedTile=targetTile;SelectedBuilding=S["cells"][SelectedTile]["building"].Text;RefreshContext();SelectionChanged?.Invoke(SelectedTile,SelectedBuilding);}},true,S["currency"].Double<cost["currency"].Double||!_proposal.Get("ok",false).Bool);Button(controls,"保留报价 · 返回地图",()=>{Runtime.Execute(g=>g.cancel_draft());CloseArchive();});
 }
 void Impact(Transform parent,V baseline,V proposal){var card=Card(parent,"建设影响 · 同一步下一结算","月率、当前库存、住房容量、电力能力与污染分别表示，不能合成一个分数。",Blue);var world=proposal["world"];foreach(var resource in new[]{"food","material","goods"}){var before=baseline["metrics"].Get("flows",V.Map()).Get(resource,0).Double;var after=world.Get("flows",V.Map()).Get(resource,0).Double;var row=Row(card,"Same Step "+resource,52);Label(row,Resource(resource),18);Label(row,"不建设 "+Signed(before)+" /月",18,Muted);Label(row,"建成后 "+Signed(after)+" /月",20,after>=before?Green:Gold);Meter(card,"当前库存（非预测库存）",G.inventory_total(resource),G.stock_cap(resource)," 单位",Blue);if(after<-.000001)Label(card,"当前库存 / 预测净消耗 ≈ "+F(G.inventory_total(resource)/-after)+"月；仅供参考，局部可达性与后续贸易会改变结果。",14,Muted);}
  Metric(card,"全城电力供给变化",Signed(proposal["energy_supply"].Double)+" 能力");Metric(card,"全城电力需求变化",Signed(proposal["energy_demand"].Double)+" 能力");Metric(card,"住房容量变化",Signed(proposal["housing"].Double)+" 人");Metric(card,"经营净额变化",Signed(proposal["cashflow"].Double)+" /月");Metric(card,"暴露上升的现有居民",F(proposal["harmed"].Double,0)+" 人","污染增加超过 0.015 的现有住户。",Gold);Fold(card,"投入、服务、竞争与完整规则来源",c=>{foreach(var resource in proposal["inputs"].Keys)Metric(c,"新增投入 · "+Resource(resource),F(proposal["inputs"][resource].Double,3)+" /月");foreach(var kind in proposal["added_service"].Keys)Metric(c,Service(kind)+"覆盖变化",Signed(proposal["added_service"][kind].Double)+" 人");foreach(var item in proposal["affected"])Label(c,G.project_name(item["id"].Text)+" 运行率变化 "+Signed(item["delta"].Double*100)+"个百分点",15,Gold);Raw(c,proposal["trace"]);});}
}
}
